#!/usr/bin/env node
// Launches the Electron dev app pointed at a synthetic test athlete's plan DB
// (generated by `npm run test:plans`, one isolated DB per athlete in backend/data/test/).
// Dev-only: this wraps `electron:dev` and is never part of electron:build/electron:publish.
const path = require('path');
const fs = require('fs');
const { spawn } = require('child_process');

const athleteId = process.argv[2];
if (!athleteId) {
  console.error('Usage: npm run electron:dev:athlete <athleteId>\n\nRun `npm run test:plans` first to generate test athlete DBs.');
  process.exit(1);
}

const repoRoot = path.join(__dirname, '..');
const dbPath = path.join(repoRoot, 'backend', 'data', 'test', `${athleteId}.db`);

if (!fs.existsSync(dbPath)) {
  console.error(
    `No test DB found for athlete "${athleteId}" at ${dbPath}\n\n` +
    'Run `npm run test:plans` first — it generates one isolated DB per athlete ' +
    'defined in backend/src/test/athletes.ts.'
  );
  process.exit(1);
}

console.log(`\n⚠  DEV MODE — loading synthetic test athlete "${athleteId}"`);
console.log(`   ${dbPath}`);
console.log('   This is NOT your real Garmin/training data.');
console.log('   Garmin login is bypassed (VELOMATE_SKIP_AUTH) — Garmin-dependent actions like');
console.log('   Sync & Schedule Workouts won\'t work against this synthetic athlete.\n');

const child = spawn('npm', ['run', 'electron:dev'], {
  cwd: repoRoot,
  stdio: 'inherit',
  shell: true,
  env: { ...process.env, VELOMATE_DB_PATH: dbPath, VELOMATE_SKIP_AUTH: '1' },
});

child.on('exit', code => process.exit(code ?? 0));
